from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    def is_expired(key, t):
        if key not in cache:
            return True
        _, wt = cache[key]
        return t >= wt + ttl

    for op in ops:
        kind = op[0]
        t = op[1]
        key = op[2]

        if kind == 'put':
            value = op[3]
            if key in cache:
                if is_expired(key, t):
                    del cache[key]
                else:
                    del cache[key]

            if len(cache) >= capacity:
                cache.popitem(last=False)

            cache[key] = (value, t)
            cache.move_to_end(key, last=True)

        elif kind == 'get':
            if key not in cache:
                results.append(-1)
            elif is_expired(key, t):
                del cache[key]
                results.append(-1)
            else:
                value, wt = cache[key]
                cache.move_to_end(key, last=True)
                results.append(value)

    return results

